  }
}

// 2. Chuyển đổi giữa Bản đồ đồ thị và Danh sách thẻ
function switchView(view) {
  const graphWrap = document.getElementById('graphContainerWrapper');
  const cardsWrap = document.getElementById('cardsContainerWrapper');
  const btnGraph = document.getElementById('btnViewGraph');
  const btnCards = document.getElementById('btnViewCards');

  if (view === 'graph') {
    graphWrap.classList.remove('hidden');
    cardsWrap.classList.add('hidden');
    btnGraph.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center space-x-1.5 transition-all bg-white text-indigo-600 shadow-sm';
    btnCards.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center space-x-1.5 transition-all text-slate-600 hover:text-slate-900';
    if (networkInstance) {
      setTimeout(() => networkInstance.fit(), 200);
    }
  } else {
    graphWrap.classList.add('hidden');
    cardsWrap.classList.remove('hidden');
    btnCards.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center space-x-1.5 transition-all bg-white text-indigo-600 shadow-sm';
    btnGraph.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center space-x-1.5 transition-all text-slate-600 hover:text-slate-900';
  }
}

// 3. Khởi tạo Bản đồ đồ thị Vis.js
async function initGraph() {
  const container = document.getElementById('graphCanvas');
  try {
    const res = await fetch('/api/graph');
    const graphData = await res.json();

    const data = {
      nodes: new vis.DataSet(graphData.nodes),
      edges: new vis.DataSet(graphData.edges)
    };

    const options = {
      nodes: {
        shape: 'box',
        borderRadius: 12,
        borderWidth: 2,
        font: { size: 14, face: 'Inter, sans-serif' },
        shadow: { enabled: true, color: 'rgba(0,0,0,0.08)', size: 8, x: 0, y: 4 }
      },
      edges: {
        width: 1.5,
        smooth: { type: 'cubicBezier', forceDirection: 'none', roundness: 0.2 },
        arrows: { to: { enabled: true, scaleFactor: 0.6 } }
      },
      physics: {
        solver: 'forceAtlas2Based',
        forceAtlas2Based: {
          gravitationalConstant: -70,
          centralGravity: 0.015,
          springLength: 120,
          springConstant: 0.08,
          damping: 0.8
        },
        stabilization: { iterations: 120 }
      },
      interaction: {
        hover: true,
        zoomView: true,
        dragView: true
      }
    };

    networkInstance = new vis.Network(container, data, options);

    // Bắt sự kiện nhấp chuột vào một quả cầu trên đồ thị
    networkInstance.on('click', function(params) {
      if (params.nodes && params.nodes.length > 0) {
        const clickedShapeId = params.nodes[0];
        openShapeModal(clickedShapeId);
      }
    });

  } catch (err) {
    console.error('Lỗi khi vẽ đồ thị Vis.js:', err);
    container.innerHTML = '<div class=\"p-8 text-center text-slate-400 text-sm\">Không thể tải bản đồ đồ thị. Vui lòng thử lại.</div>';
  }
}

