    currentModalShape = shape;

    document.getElementById('modalShapeName').textContent = shape.name;
    document.getElementById('modalShapeEn').textContent = shape.name_en;
    document.getElementById('modalDefinition').textContent = shape.definition;
    document.getElementById('modalSides').textContent = shape.sides_count > 0 ? shape.sides_count + ' cạnh, ' + shape.vertices_count + ' đỉnh' : 'Đường cong khép kín';
    document.getElementById('modalAngles').textContent = shape.sum_interior_angles + '°';

    // Nguồn SGK
    const cite = document.getElementById('modalSourceCitation');
    cite.textContent = shape.source_id + ' (' + shape.source_locator + ') • ' + (shape.verified_by || 'Đã duyệt');

