// 7. Thiết lập Tab Máy tính
function setupCalculatorTab(shape) {
  const radioGroup = document.getElementById('formulaTypeRadios');
  radioGroup.innerHTML = '';
  document.getElementById('calculationResultBox').classList.add('hidden');

  currentFormulaType = shape.formulas[0].type;

  shape.formulas.forEach((f, idx) => {
    const label = document.createElement('label');
    label.className = 'px-3 py-1.5 rounded-xl border text-xs font-semibold cursor-pointer transition-all ' +
      (idx === 0 ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-600 border-slate-200');
    label.innerHTML = `
      <input type="radio" name="formulaChoice" value="${f.type}" class="hidden" ${idx === 0 ? 'checked' : ''} onchange="changeFormulaType('${f.type}')">
      ${f.type}
    `;
    radioGroup.appendChild(label);
  });

  renderCalculatorInputs(shape, currentFormulaType);
}

function changeFormulaType(type) {
  currentFormulaType = type;
  document.querySelectorAll('input[name="formulaChoice"]').forEach(r => {
    if (r.value === type) {
      r.parentElement.className = 'px-3 py-1.5 rounded-xl border text-xs font-semibold cursor-pointer transition-all bg-indigo-600 text-white border-indigo-600';
    } else {
      r.parentElement.className = 'px-3 py-1.5 rounded-xl border text-xs font-semibold cursor-pointer transition-all bg-white text-slate-600 border-slate-200';
    }
  });
  renderCalculatorInputs(currentModalShape, type);
}

function renderCalculatorInputs(shape, type) {
  const container = document.getElementById('calculatorInputFields');
  container.innerHTML = '';
  document.getElementById('calculationResultBox').classList.add('hidden');

  const formula = shape.formulas.find(f => f.type === type);
  if (!formula) return;

  formula.params.forEach(p => {
    const field = document.createElement('div');
    field.className = 'space-y-1.5';
    field.innerHTML = `
      <label class="text-xs font-semibold text-slate-700 block">${p.label}:</label>
      <div class="relative">
        <input type="number" step="any" id="calc_input_${p.name}" value="${p.default}" 
               class="w-full px-3.5 py-2.5 bg-slate-50 focus:bg-white rounded-xl border border-slate-200 focus:border-indigo-500 text-xs font-semibold outline-none transition-all">
        <span class="absolute right-3.5 top-2.5 text-xs text-slate-400 font-medium">${p.unit}</span>
      </div>
    `;
    container.appendChild(field);
  });
}

async function submitCalculation() {
  if (!currentModalShape) return;
  const formula = currentModalShape.formulas.find(f => f.type === currentFormulaType);
  if (!formula) return;

  const inputs = {};
  for (const p of formula.params) {
    const inputEl = document.getElementById('calc_input_' + p.name);
    if (!inputEl || inputEl.value === '') {
      alert('Vui lòng nhập đầy đủ giá trị cho ' + p.label);
      return;
    }
    inputs[p.name] = inputEl.value;
  }

  try {
    const res = await fetch('/api/calculate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        shape_id: currentModalShape.id,
        formula_type: currentFormulaType,
        inputs: inputs
      })
    });

    const data = await res.json();
    if (!res.ok) {
      alert(data.error || 'Có lỗi khi tính toán');
      return;
    }

    const box = document.getElementById('calculationResultBox');
    box.classList.remove('hidden');
    document.getElementById('calcFinalResult').textContent = data.result + ' ' + data.unit;

    const stepList = document.getElementById('calcStepList');
    stepList.innerHTML = '';
    data.steps.forEach(s => {
      const p = document.createElement('p');
      p.textContent = s;
      stepList.appendChild(p);
    });

  } catch (err) {
    console.error('Lỗi tính toán:', err);
    alert('Không thể thực hiện phép tính');
  }
}

// 8. Bản đồ chỉ đường chứng minh (UC05)
function loadProofSelects() {
  const startSelect = document.getElementById('proofStartSelect');
  const endSelect = document.getElementById('proofEndSelect');

  startSelect.innerHTML = '';
  endSelect.innerHTML = '';

  const candidates = [
    { id: 'SHAPE_TRAPEZOID', name: 'Hình thang' },
    { id: 'SHAPE_PARALLELOGRAM', name: 'Hình bình hành' },
    { id: 'SHAPE_RECTANGLE', name: 'Hình chữ nhật' },
    { id: 'SHAPE_RHOMBUS', name: 'Hình thoi' },
    { id: 'SHAPE_SQUARE', name: 'Hình vuông' },
    { id: 'SHAPE_ISOSCELES_TRAPEZOID', name: 'Hình thang cân' }
  ];

  candidates.forEach((c, idx) => {
    const opt1 = new Option(c.name, c.id);
    const opt2 = new Option(c.name, c.id);
    if (idx === 1) opt1.selected = true; // Hình bình hành
    if (idx === 4) opt2.selected = true; // Hình vuông
    startSelect.add(opt1);
    endSelect.add(opt2);
  });
}

