              <p class="text-slate-600 mt-1 text-[11px]"><span class="font-semibold text-slate-700">Điều kiện cần chứng minh:</span> ${s.condition}</p>
            </div>
          </div>
        `;
      });

      pathCard.innerHTML = `
        <div class="flex items-center justify-between border-b border-slate-200 pb-2">
          <span class="text-xs font-bold text-slate-800"><i class="fa-solid fa-route text-emerald-600 mr-1.5"></i>${p.title}</span>
          <span class="text-[11px] px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 font-semibold">${p.steps.length} chặng</span>
