let quizData = [];
async function openQuizModal() {
  const container = document.getElementById('quizContainer');
  container.innerHTML = '<div class=\"p-6 text-center text-xs text-slate-400\"><i class=\"fa-solid fa-spinner fa-spin mr-2\"></i>Đang tải câu hỏi trắc nghiệm...</div>';
  document.getElementById('quizModal').classList.remove('hidden');

  try {
    const res = await fetch('/api/quiz');
    quizData = await res.json();
    renderQuizQuestions();
  } catch (err) {
    container.innerHTML = '<div class=\"p-4 bg-rose-50 text-rose-700 text-xs rounded-xl\">Lỗi tải câu hỏi</div>';
  }
}

function closeQuizModal() {
  document.getElementById('quizModal').classList.add('hidden');
}

function renderQuizQuestions() {
  const container = document.getElementById('quizContainer');
  container.innerHTML = '';

  quizData.forEach((q, idx) => {
    const qCard = document.createElement('div');
    qCard.className = 'p-5 bg-slate-50 rounded-2xl border border-slate-200 space-y-4';
    qCard.id = 'quizCard_' + q.id;

    let optionsHtml = '';
    q.options.forEach((opt, optIdx) => {
      optionsHtml += `
        <label class="flex items-center space-x-3 p-3 bg-white rounded-xl border border-slate-200 hover:border-indigo-400 cursor-pointer text-xs transition-colors">
          <input type="radio" name="quiz_opt_${q.id}" value="${optIdx}" class="text-indigo-600 focus:ring-indigo-500">
          <span class="text-slate-700 font-medium">${opt}</span>
        </label>
      `;
    });

    qCard.innerHTML = `
      <div class="flex items-start justify-between">
        <span class="text-xs font-bold text-slate-900 leading-relaxed">Câu ${idx + 1}: ${q.question}</span>
      </div>
      <div class="space-y-2">${optionsHtml}</div>
      <div class="flex items-center justify-between pt-2">
        <button onclick="revealHint('${q.id}')" class="text-xs font-semibold text-amber-600 hover:text-amber-700 flex items-center space-x-1">
          <i class="fa-solid fa-lightbulb"></i>
          <span>Cần gợi ý?</span>
        </button>
        <button onclick="checkQuizAnswer('${q.id}', ${q.answer})" class="px-4 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold transition-all">
          Kiểm tra đáp án
        </button>
      </div>
      <div id="hintBox_${q.id}" class="hidden p-3 bg-amber-50 rounded-xl border border-amber-200 text-xs text-amber-800 space-y-1"></div>
      <div id="resultBox_${q.id}" class="hidden p-3 rounded-xl text-xs space-y-1"></div>
    `;
    container.appendChild(qCard);
  });
}

const hintLevels = {};
function revealHint(qId) {
  if (!hintLevels[qId]) hintLevels[qId] = 0;
  const q = quizData.find(item => item.id === qId);
  if (!q || !q.hints) return;

  const box = document.getElementById('hintBox_' + qId);
  box.classList.remove('hidden');

  if (hintLevels[qId] < q.hints.length) {
    const hintText = document.createElement('p');
    hintText.textContent = q.hints[hintLevels[qId]];
    box.appendChild(hintText);
    hintLevels[qId]++;
  } else {
    alert('Đã hiển thị tối đa các tầng gợi ý cho câu hỏi này!');
  }
}

function checkQuizAnswer(qId, correctIdx) {
  const selected = document.querySelector('input[name="quiz_opt_' + qId + '\"]:checked');
  const resBox = document.getElementById('resultBox_' + qId);
  resBox.classList.remove('hidden');

  const q = quizData.find(item => item.id === qId);

  if (!selected) {
    alert('Vui lòng chọn một đáp án');
    return;
  }

  const chosen = parseInt(selected.value);
  if (chosen === correctIdx) {
    resBox.className = 'p-3 rounded-xl text-xs space-y-1 bg-emerald-50 text-emerald-800 border border-emerald-200';
    resBox.innerHTML = '<p class=\"font-bold\"><i class=\"fa-solid fa-circle-check mr-1\"></i>Chính xác!</p><p>' + q.explanation + '</p>';
  } else {
    resBox.className = 'p-3 rounded-xl text-xs space-y-1 bg-rose-50 text-rose-800 border border-rose-200';
    resBox.innerHTML = '<p class=\"font-bold\"><i class=\"fa-solid fa-circle-xmark mr-1\"></i>Chưa chính xác!</p><p>Đáp án đúng: ' + q.options[correctIdx] + '. ' + q.explanation + '</p>';
  }
}

// 11. Trợ lý hình học GeoBot (UC08)
function toggleChatbot() {
  const box = document.getElementById('chatbotBox');
  box.classList.toggle('hidden');
}

async function sendChatMessage() {
  const input = document.getElementById('chatInput');
  const question = input.value.trim();
  if (!question) return;

  const messages = document.getElementById('chatMessages');

  // Thêm tin nhắn người dùng
  const userMsg = document.createElement('div');
  userMsg.className = 'flex justify-end';
  userMsg.innerHTML = '<div class=\"p-3 bg-indigo-600 text-white rounded-2xl rounded-tr-none leading-relaxed text-xs max-w-[85%]\">' + question + '</div>';
  messages.appendChild(userMsg);

  input.value = '';
  messages.scrollTop = messages.scrollHeight;

  // Gọi API chatbot
  try {
    const res = await fetch('/api/chatbot', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ question: question })
    });
    const data = await res.json();

    const botMsg = document.createElement('div');
    botMsg.className = 'flex items-start space-x-2';

    let openBtn = '';
    if (data.related_shape_id) {
      openBtn = `<button onclick="openShapeModal('${data.related_shape_id}')" class="mt-2 text-[11px] font-bold text-indigo-600 hover:text-indigo-800 block underline"><i class="fa-solid fa-eye mr-1"></i>Mở hồ sơ hình này ra xem thử</button>`;
    }

    botMsg.innerHTML = `
      <div class="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">
        <i class="fa-solid fa-robot"></i>
      </div>
      <div class="p-3 bg-slate-100 rounded-2xl rounded-tl-none text-slate-700 leading-relaxed text-xs max-w-[85%]">
        ${data.reply}
        ${openBtn}
      </div>
    `;
    messages.appendChild(botMsg);
    messages.scrollTop = messages.scrollHeight;

  } catch (err) {
    console.error('Lỗi chatbot:', err);
  }
}

// 12. Tìm kiếm nhanh
function handleSearch(event) {
  const query = event.target.value.toLowerCase().trim();
  const box = document.getElementById('searchResults');

  if (!query) {
    box.classList.add('hidden');
    box.innerHTML = '';
    return;
  }

  const matches = allShapes.filter(s => 
    s.name.toLowerCase().includes(query) || 
    s.name_en.toLowerCase().includes(query) ||
    s.definition.toLowerCase().includes(query)
  );

  if (matches.length === 0) {
    box.innerHTML = '<div class=\"p-3 text-xs text-slate-400 text-center\">Không tìm thấy hình nào khớp với từ khóa</div>';
  } else {
    box.innerHTML = '';
    matches.forEach(m => {
      const item = document.createElement('div');
      item.className = 'p-2.5 hover:bg-slate-50 rounded-xl cursor-pointer flex items-center space-x-2.5 transition-colors';
      item.onclick = () => {
        openShapeModal(m.id);
        box.classList.add('hidden');
      };
      item.innerHTML = `
        <div class="w-7 h-7 rounded-lg text-white font-bold text-xs flex items-center justify-center" style="background-color: ${m.color || '#4f46e5'}">
          <i class="fa-solid fa-shapes"></i>
        </div>
        <div>
          <span class="text-xs font-bold text-slate-800 block">${m.name}</span>
          <span class="text-[10px] text-slate-400 block">${m.name_en}</span>
        </div>
      `;
      box.appendChild(item);
    });
  }

  box.classList.remove('hidden');
}
