// 2. Lấy dữ liệu đồ thị trực quan cho Vis.js (Nodes và Edges)
app.get('/api/graph', (req, res) => {
  const nodes = graphData.shapes.map(s => ({
    id: s.id,
    label: s.name,
    title: s.name_en + ': ' + s.definition,
    color: {
      background: s.color || '#4f46e5',
      border: '#ffffff',
      highlight: { background: '#f59e0b', border: '#ffffff' }
    },
    font: { color: '#ffffff', size: 14, face: 'Segoe UI, sans-serif' },
    shape: 'box',
    margin: 10,
    shadow: true
  }));

  const edges = [];
  // Cạnh kế thừa IS_A
  graphData.shapes.forEach(s => {
    if (s.parents && s.parents.length > 0) {
      s.parents.forEach(pId => {
        edges.push({
          from: s.id,
          to: pId,
          label: 'kế thừa (là một)',
          arrows: 'to',
          color: { color: '#94a3b8' },
          dashes: true,
          font: { size: 10, color: '#64748b' }
        });
      });
    }
  });

  // Cạnh chuyển đổi TRANSFORMS_TO
  graphData.transitions.forEach((t, idx) => {
    edges.push({
      id: 'trans_' + idx,
      from: t.from,
      to: t.to,
      label: t.condition.length > 25 ? t.condition.substring(0, 25) + '...' : t.condition,
      arrows: 'to',
      color: { color: '#3b82f6', highlight: '#f59e0b' },
      font: { size: 11, color: '#2563eb' }
    });
  });

  res.json({ nodes, edges });
});

