async function initGraph() {
  const container = document.getElementById('graphCanvas');
  try {
    const res = await fetch('/api/graph');
    const data = await res.json();

    const options = {
      nodes: {
        shape: 'box',
        margin: { top: 10, bottom: 10, left: 16, right: 16 },
        shadow: { enabled: true, color: 'rgba(0,0,0,0.1)', size: 8, x: 2, y: 3 },
        borderWidth: 2,
        font: { face: 'Inter, sans-serif', size: 14, color: '#ffffff', bold: { mod: 'bold' } }
      },
      edges: {
        smooth: { type: 'cubicBezier', forceDirection: 'vertical', roundness: 0.35 },
        font: { face: 'Inter, sans-serif', size: 11, align: 'horizontal', background: '#ffffff', strokeWidth: 0 },
        arrows: { to: { enabled: true, scaleFactor: 0.9 } }
      },
      layout: {
        hierarchical: {
          direction: 'UD',
          sortMethod: 'directed',
          levelSeparation: 115,
          nodeSpacing: 180,
          treeSpacing: 200,
          blockShifting: true,
          edgeMinimization: true,
          parentCentralization: true
        }
      },
      physics: {
        hierarchicalRepulsion: {
          nodeDistance: 170
        }
      },
      interaction: { hover: true, tooltipDelay: 100 }
    };

    networkInstance = new vis.Network(container, data, options);

    networkInstance.on('click', function(params) {
      if (params.nodes.length > 0) {
        const nodeId = params.nodes[0];
        openShapeModal(nodeId);
      }
    });

    networkInstance.once('stabilizationIterationsDone', function () {
      networkInstance.fit({ animation: { duration: 600, easingFunction: 'easeInOutQuad' } });
    });
  } catch (err) {
    console.error('Lỗi khi vẽ đồ thị Vis.js:', err);
  }
}

